# Vulnerability details

## Vulnerability details
`expressExecute` is intended to be called by an Express Relayer, that charges fees for express executing. The issue is that malicious users can transfer tokens from a chain with a valid token manager to a different chain where there is no token manager deployed, connected to the original `tokenId`. As a result, the Express Relayer will express execute the transfer, transferring funds to the destination address with the expectation of receiving those funds at a later time. However, they will be unable to get back their funds, as the required token manager will not have been deployed on the destination chain.

## Impact
As a result, malicious users will be able to grief the Express Relayer, causing a great loss of funds.


## Proof of Concept
When `interchainTransfer` is called there is no way to know whether a token manager, corresponding to the `tokenId`, has been deployed on the destination chain:
```solidity
function interchainTransfer(
        bytes32 tokenId,
        string calldata destinationChain,
        bytes calldata destinationAddress,
        uint256 amount,
        bytes calldata metadata,
        uint256 gasValue
    ) external payable whenNotPaused {
        string memory symbol;
        (amount, symbol) = _takeToken(tokenId, msg.sender, amount, false);

        (IGatewayCaller.MetadataVersion metadataVersion, bytes memory data) = _decodeMetadata(metadata);

        _transmitInterchainTransfer(
            tokenId,
            msg.sender,
            destinationChain,
            destinationAddress,
            amount,
            metadataVersion,
            data,
            symbol,
            gasValue
        );
    }
```

This leaves the Express Relayer vulnerable to losing funds as `expressExecute` will not fail even if there is not a deployed token manager:
```solidity
 function _expressExecute(bytes32 commandId, string calldata sourceChain, bytes calldata payload) internal {
        (, bytes32 tokenId, bytes memory sourceAddress, bytes memory destinationAddressBytes, uint256 amount, bytes memory data) = abi
            .decode(payload, (uint256, bytes32, bytes, bytes, uint256, bytes));
        address destinationAddress = destinationAddressBytes.toAddress();

        IERC20 token;
        {
            (bool success, bytes memory returnData) = tokenHandler.delegatecall(
                abi.encodeWithSelector(ITokenHandler.transferTokenFrom.selector, tokenId, msg.sender, destinationAddress, amount)
            );
            if (!success) revert TokenHandlerFailed(returnData);
            (amount, token) = abi.decode(returnData, (uint256, IERC20));
        }

        // slither-disable-next-line reentrancy-events
        emit InterchainTransferReceived(
            commandId,
            tokenId,
            sourceChain,
            sourceAddress,
            destinationAddress,
            amount,
            data.length == 0 ? bytes32(0) : keccak256(data)
        );

        if (data.length != 0) {
            bytes32 result = IInterchainTokenExpressExecutable(destinationAddress).expressExecuteWithInterchainToken(
                commandId,
                sourceChain,
                sourceAddress,
                data,
                tokenId,
                address(token),
                amount
            );

            if (result != EXPRESS_EXECUTE_SUCCESS) revert ExpressExecuteWithInterchainTokenFailed(destinationAddress);
        }
    }
```

After the Express Relayer has transferred funds to the destination address, they will be unable to reclaim the tokens as `TokenHandler.giveToken`, called in `execute -> _execute -> _processInterchainTransferPayload -> _giveToken`, will revert as there will not be any code deployed on `tokenManager`:
```solidity
function giveToken(bytes32 tokenId, address to, uint256 amount) external payable returns (uint256, address) {
        address tokenManager = _create3Address(tokenId);
        //@audit Will revert here, as tokenManager will not have any code
        (uint256 tokenManagerType, address tokenAddress) = ITokenManagerProxy(tokenManager).getImplementationTypeAndTokenAddress();

        /// @dev Track the flow amount being received via the message
        ITokenManager(tokenManager).addFlowIn(amount);

        if (tokenManagerType == uint256(TokenManagerType.NATIVE_INTERCHAIN_TOKEN)) {
            _giveInterchainToken(tokenAddress, to, amount);
            return (amount, tokenAddress);
        }

        if (tokenManagerType == uint256(TokenManagerType.MINT_BURN) || tokenManagerType == uint256(TokenManagerType.MINT_BURN_FROM)) {
            _mintToken(tokenManager, tokenAddress, to, amount);
            return (amount, tokenAddress);
        }

        if (tokenManagerType == uint256(TokenManagerType.LOCK_UNLOCK)) {
            _transferTokenFrom(tokenAddress, tokenManager, to, amount);
            return (amount, tokenAddress);
        }

        if (tokenManagerType == uint256(TokenManagerType.LOCK_UNLOCK_FEE)) {
            amount = _transferTokenFromWithFee(tokenAddress, tokenManager, to, amount);
            return (amount, tokenAddress);
        }

        if (tokenManagerType == uint256(TokenManagerType.GATEWAY)) {
            _transferToken(tokenAddress, to, amount);
            return (amount, tokenAddress);
        }

        revert UnsupportedTokenManagerType(tokenManagerType);
    }
```

